private fun checkOnStatue(row: Int, col: Int, statues: List<Position>): Boolean {
    for (statue in statues) {
        if (row == statue.row && col == statue.col) {
            return true
        }
    }
    return false
}

private fun dfs(row: Int, col: Int, statues: List<Position>, used: Long): Int {
    if (row < 0 || col < 0 || row >= 8 || col >= 8) {
        return 0
    }

    val bit = 1L shl (row * 8 + col)
    if ((used and bit) != 0L || checkOnStatue(row, col, statues)) {
        return 0
    }

    if (row == 0 && col == 7) {
        solved = true
        return 1
    }

    val movedStatues = statues.map { Position(it.row + 1, it.col) }

    if (checkOnStatue(row, col, movedStatues)) {
        return 0
    }

    val newUsed = used or bit
    val directions = arrayOf(
        intArrayOf(-1, 0),
        intArrayOf(0, 1),
        intArrayOf(0, -1),
        intArrayOf(1, 0),
        intArrayOf(1, 1),
        intArrayOf(1, -1),
        intArrayOf(-1, 1),
        intArrayOf(-1, -1),
        intArrayOf(0, 0)
    )

    var result = 0
    for (direction in directions) {
        result = maxOf(
            result,
            dfs(
                row + direction[0],
                col + direction[1],
                movedStatues,
                newUsed
            )
        )
        if (solved) {
            return 1
        }
    }

    return result
}

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun next(): String {
        val result = StringBuilder()
        var c: Int
        do {
            c = readByte()
        } while (c <= 32 && c != -1)

        while (c > 32 && c != -1) {
            result.append(c.toChar())
            c = readByte()
        }
        return result.toString()
    }
}

fun main() {
    val scanner = FastScanner()
    val statues = mutableListOf<Position>()

    for (i in 0 until 8) {
        val row = scanner.next()
        for (j in 0 until 8) {
            if (row[j] == 'S') {
                statues.add(Position(i, j))
            }
        }
    }

